+
+  .details summary {
+    padding: var(--space-md);
+    font-size: 1rem;
+  }
+
+  .details p {
+    padding: var(--space-md);
+  }
+}
+
+@media (max-width: 480px) {
+  h1 {
+    font-size: 1.5rem;
