+    outline: 3px solid Highlight;
+  }
+
+  .details summary::marker {
+    color: CanvasText;
+  }
+
+  .details summary::before {
+    color: CanvasText;
+  }
+
+  .details[open] {
+    border: 2px solid Highlight;
+  }
+}
+
+/* Print styles */
+@media print {
+  header {
+    background: none;
+    border: none;
+  }
+
