/**
 * Accessibility enhancements for FAQ disclosure widgets
 * - Keyboard support (Escape to close)
 * - Focus management
 * - Smooth animation support
 */

document.addEventListener('DOMContentLoaded', () => {
  const details = document.querySelectorAll('.details');

  details.forEach((element) => {
    // Add keyboard support: Escape closes the disclosure
    element.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && element.open) {
        event.preventDefault();
        element.open = false;
        // Return focus to the summary
        element.querySelector('summary').focus();
      }
    });

    // Enhance focus styling
    const summary = element.querySelector('summary');
    summary.addEventListener('focus', () => {
      summary.setAttribute('data-focused', 'true');
    });

    summary.addEventListener('blur', () => {
      summary.removeAttribute('data-focused');
    });
  });

  // Optional: Announce open/close state to screen readers
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      if (mutation.type === 'attributes' && mutation.attributeName === 'open') {
        const details = mutation.target;
        const summary = details.querySelector('summary');
        const isOpen = details.hasAttribute('open');

        // Update aria-expanded for clarity
        if (!summary.hasAttribute('aria-expanded')) {
          summary.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        } else {
          summary.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        }
      }
    });
  });

  details.forEach((element) => {
    const summary = element.querySelector('summary');
    // Initialize aria-expanded
    summary.setAttribute('aria-expanded', element.hasAttribute('open') ? 'true' : 'false');

    // Observe changes
    observer.observe(element, {
      attributes: true,
      attributeFilter: ['open'],
    });
  });
});

